import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
CONVERT_BIN = os.environ.get('CONVERT_BIN', '/usr/bin/convert')

os.makedirs(UPLOAD_DIR, exist_ok=True)

@app.route('/health')
def health():
    return jsonify(status='ok')

@app.route('/upload', methods=['POST'])
def upload_image():
    """Upload an image and convert it to PNG using ImageMagick."""
    if 'file' not in request.files:
        return jsonify(error='No file provided'), 400

    f = request.files['file']
    if not f.filename:
        return jsonify(error='Empty filename'), 400

    filename = secure_filename(f.filename)
    if not filename:
        return jsonify(error='Invalid filename'), 400

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, filename)
    f.save(input_path)

    # Convert to PNG using ImageMagick
    output_filename = os.path.splitext(filename)[0] + '.png'
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Build conversion command
    cmd = f'{CONVERT_BIN} {input_path} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30
        )
        if result.returncode != 0:
            return jsonify(error='Conversion failed', detail=result.stderr.decode('utf-8', errors='replace')), 500
    except subprocess.TimeoutExpired:
        return jsonify(error='Conversion timed out'), 504
    finally:
        # Clean up input file
        if os.path.exists(input_path):
            os.unlink(input_path)

    return jsonify(success=True, output=output_filename)

@app.route('/images/<filename>')
def get_image(filename):
    """Retrieve a converted image."""
    safe_name = secure_filename(filename)
    if not safe_name:
        return jsonify(error='Invalid filename'), 400
    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if not os.path.exists(filepath):
        return jsonify(error='Not found'), 404
    return send_file(filepath, mimetype='image/png')

@app.route('/resize', methods=['POST'])
def resize_image():
    """Resize an already-uploaded image."""
    data = request.get_json()
    if not data or 'filename' not in data or 'dimensions' not in data:
        return jsonify(error='Missing parameters'), 400

    filename = secure_filename(data['filename'])
    dimensions = data['dimensions']  # e.g. "800x600"

    if not filename:
        return jsonify(error='Invalid filename'), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(input_path):
        return jsonify(error='File not found'), 404

    output_filename = f"resized_{filename}"
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Resize using ImageMagick - dimensions is user-controlled
    cmd = f'{CONVERT_BIN} {input_path} -resize {dimensions} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30
        )
        if result.returncode != 0:
            return jsonify(error='Resize failed', detail=result.stderr.decode('utf-8', errors='replace')), 500
    except subprocess.TimeoutExpired:
        return jsonify(error='Resize timed out'), 504

    return jsonify(success=True, output=output_filename)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
